#include "TestFixture.hpp"
#include "Controller.hpp"
using namespace mhmvalidation;using namespace validationtest;
namespace {
struct MemoryTrace:TraceWriter {bool fail=false;std::vector<TraceRecord> rows;bool Append(const TraceRecord& r)override{if(fail)return false;rows.push_back(r);return true;}};
void Connect(SdkSession& s){Check(s.Connect(Api(),&MhwMorphGetAssetIdentity)==MHM_OK,"connect controller fixture");}
void TestStartReadOnly(){Fixture f;Attach();auto c=TestCatalog();SdkSession s;Connect(s);MemoryTrace trace;Controller ctl(s,c,trace);ctl.Tick(0);auto v=ctl.GetSnapshot();Check(v.phase==Phase::NotStarted&&!v.started&&!v.pending&&s.Source()==0,"startup only discovers");Check(!ctl.Dispatch(Action::NextStep,1)&&s.Source()==0,"no step without explicit Begin");}
void TestBeginCombination(){Fixture f;Attach();auto c=TestCatalog();SdkSession s;Connect(s);MemoryTrace trace;Controller ctl(s,c,trace);ctl.Tick(0);Check(ctl.Dispatch(Action::NextCase,1),"navigation requests zero");Check(ctl.GetSnapshot().caseIndex==0&&ctl.GetSnapshot().pending,"no selection before zero applied");Apply();ctl.Tick(100);Check(ctl.GetSnapshot().caseIndex==1&&ctl.GetSnapshot().phase==Phase::NotStarted,"zero then select not started");Check(ctl.Dispatch(Action::Begin,101),"begin selected combination");auto o=s.Read();Check(std::count_if(o.weights.begin(),o.weights.end(),[](const auto& w){return w.requested==.5f;})==25,"Begin establishes 25 fixed keys");Apply();ctl.Tick(200);Check(ctl.GetSnapshot().phase==Phase::Holding,"core applied combination");}
void TestNavigationWaitsForZero(){Fixture f;Attach();auto c=TestCatalog();SdkSession s;Connect(s);MemoryTrace trace;Controller ctl(s,c,trace);ctl.Tick(0);ctl.Dispatch(Action::Begin,1);Check(!ctl.Dispatch(Action::NextCase,2),"cannot navigate pending apply");Apply();ctl.Tick(100);ctl.Dispatch(Action::NextStep,101);Apply();ctl.Tick(200);ctl.Dispatch(Action::NextCase,201);Check(ctl.GetSnapshot().phase==Phase::WaitingZero&&!ctl.Dispatch(Action::NextCase,202),"only one navigation while zero pending");ctl.Tick(300);Check(ctl.GetSnapshot().caseIndex==0,"zero submission alone cannot switch");Apply();ctl.Tick(400);Check(ctl.GetSnapshot().caseIndex==1&&!ctl.GetSnapshot().started,"next case waits explicit Begin");}
void TestCombinationLastStepVsZero(){Fixture f;Attach();auto c=TestCatalog();SdkSession s;Connect(s);MemoryTrace trace;Controller ctl(s,c,trace);ctl.Tick(0);ctl.Dispatch(Action::NextCase,1);Apply();ctl.Tick(100);ctl.Dispatch(Action::Begin,101);Apply();ctl.Tick(200);for(uint64_t i=0;i<8;++i){Check(ctl.Dispatch(Action::NextStep,201+i*100),"advance nine-step curve");Apply();ctl.Tick(300+i*100);}auto o=s.Read();Check(std::count_if(o.weights.begin(),o.weights.end(),[](const auto& w){return w.applied==.5f;})==25,"tail retains fixed weights");Check(!ctl.Dispatch(Action::NextStep,1101),"last step bounded");Check(ctl.Dispatch(Action::ZeroAll,1102),"explicit zero all");Apply();ctl.Tick(1200);o=s.Read();Check(std::all_of(o.weights.begin(),o.weights.end(),[](const auto& w){return w.requested==0&&w.applied==0;}),"all actual keys zero");Check(s.Source()!=0&&!ctl.GetSnapshot().started,"zero retains source");}
void TestCloseCancelsPendingNonzero(){Fixture f;const auto h=Attach();Source lower;lower.Set(h,.25f);auto c=TestCatalog();SdkSession s;Connect(s);MemoryTrace trace;Controller ctl(s,c,trace);ctl.Tick(0);ctl.Dispatch(Action::Begin,1);Apply();ctl.Tick(100);ctl.Dispatch(Action::NextStep,101);Check(s.Read().weights[0].requested==.25f,"nonzero operation pending before close");Check(ctl.Dispatch(Action::End,102),"End overrides pending nonzero operation");Check(!ctl.Dispatch(Action::Begin,103)&&!ctl.GetSnapshot().finished,"ending cannot queue nonzero or finish early");Apply();ctl.Tick(200);auto v=ctl.GetSnapshot();Check(v.phase==Phase::Ended&&v.finished&&v.normalEnd&&s.Source()==0,"zero acknowledged before normal release");auto o=s.Read();Check(o.weights[0].requested==.25f&&o.weights[0].source==lower.id,"release reveals lower layer and does not promise persistent zero");}
void TestFocusLossKeepsLease(){Fixture f;Attach();auto c=TestCatalog();SdkSession s;Connect(s);MemoryTrace trace;Controller ctl(s,c,trace);ctl.Tick(0);ctl.Dispatch(Action::Begin,1);Apply();ctl.Tick(100);ctl.Dispatch(Action::NextStep,101);Apply();ctl.Tick(200);const auto source=s.Source();for(unsigned i=1;i<=8;++i){Advance(500);ctl.Tick(200+i*500);}Check(s.Source()==source&&ctl.GetSnapshot().phase==Phase::Holding&&s.Read().weights[0].requested==.25f,"no focus event releases or advances case");}
void TestTimeoutAndTargetChange(){for(bool replace:{false,true}){Fixture f;auto h=Attach();auto c=TestCatalog();SdkSession s;Connect(s);MemoryTrace trace;Controller ctl(s,c,trace);ctl.Tick(0);ctl.Dispatch(Action::Begin,1);if(replace){Core().Detach(h);Attach();ctl.Tick(100);}else ctl.Tick(5100);auto v=ctl.GetSnapshot();Check(v.phase==Phase::Interrupted&&!v.started&&!v.normalEnd&&s.Source()==0,"unconfirmed operation interrupted and released");ctl.Tick(5200);Check(!ctl.GetSnapshot().started,"rediscovery never restarts a case");}}
void TestEvidenceFailureKeepsCleanup(){Fixture f;Attach();auto c=TestCatalog();SdkSession s;Connect(s);MemoryTrace trace;Controller ctl(s,c,trace);ctl.Tick(0);ctl.Dispatch(Action::Begin,1);Apply();ctl.Tick(100);trace.fail=true;Check(!ctl.Dispatch(Action::NextStep,101),"failed intent record blocks new nonzero step");Check(!ctl.GetSnapshot().evidenceComplete&&s.Read().weights[0].requested==0,"evidence failure visible without nonzero submit");Check(ctl.Dispatch(Action::End,102),"cleanup allowed despite evidence failure");Apply();ctl.Tick(200);Check(ctl.GetSnapshot().finished&&s.Source()==0,"cleanup releases even with broken log");}
void TestCoveredZeroCannotFinish(){Fixture f;auto h=Attach();Source mask(201);mask.Set(h,0);auto c=TestCatalog();SdkSession s;Connect(s);MemoryTrace trace;Controller ctl(s,c,trace);ctl.Tick(0);ctl.Dispatch(Action::End,1);Apply();ctl.Tick(100);Check(!ctl.GetSnapshot().finished&&ctl.GetSnapshot().phase==Phase::Covered,"same numeric zero is not own confirmation");ctl.Tick(5100);auto v=ctl.GetSnapshot();Check(v.finished&&!v.normalEnd&&v.phase==Phase::Interrupted,"covered zero cannot claim normal end");}
void TestZeroHoldCoverageRevokesConfirmation(){Fixture f;auto h=Attach();auto c=TestCatalog();SdkSession s;Connect(s);MemoryTrace trace;Controller ctl(s,c,trace);ctl.Tick(0);ctl.Dispatch(Action::ZeroAll,1);Apply();ctl.Tick(100);Check(ctl.GetSnapshot().zeroConfirmed,"initial zero confirmed");Source higher(201);higher.Set(h,0);Apply();ctl.Tick(200);auto v=ctl.GetSnapshot();Check(v.phase==Phase::Covered&&!v.zeroConfirmed&&!v.applicationConfirmed,"equal zero from a new owner revokes held zero receipt");}
void TestTraceEncodingAndBound(){TraceRecord record;record.event="quoted\" name";record.error="目\nline";record.reference.mode="BASELINE";record.reference.liveIds={"key_0"};record.targets={.25f};record.observation.weights={{.25f,.0f,3}};auto line=EncodeTrace(record);Check(line.find("\\\"")!=line.npos&&morphpreset::json::Reader(Quote(record.error)).Parse().text==record.error&&line.find("目")!=line.npos,"UTF8 JSON escaping round trip");Check(line.find("visual_passed")==line.npos&&line.find("\"target\":0.25")!=line.npos,"trace is not visual acceptance");auto path=std::filesystem::path("trace-synthetic-"+std::to_string(GetCurrentProcessId())+".ndjson");{FileTraceWriter file(path,line.size());Check(file.Append(record),"first bounded record written");Check(!file.Append(record),"evidence size limit rejects without truncation");}Check(std::filesystem::file_size(path)==line.size(),"previous record intact");std::filesystem::remove(path);}
}
int main(){try{TestStartReadOnly();TestBeginCombination();TestNavigationWaitsForZero();TestCombinationLastStepVsZero();TestCloseCancelsPendingNonzero();TestFocusLossKeepsLease();TestTimeoutAndTargetChange();TestEvidenceFailureKeepsCleanup();TestCoveredZeroCannotFinish();TestZeroHoldCoverageRevokesConfirmation();TestTraceEncodingAndBound();std::printf("PASS: %u controller/trace checks\n",checks);return 0;}catch(const std::exception& e){std::printf("FAIL: %s\n",e.what());return 1;}}
